'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output');fs.mkdirSync(OUT,{recursive:true});const OWNER='p14_owner_260804221827';
function creds(){const e=process.env.P11_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return creds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function loginTry(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(p.url())}catch{}return{ok,c,p}}
function cand(text,vals){const x=[...vals];for(const m of String(text).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))x.push(m[0]);return[...new Set(x)].filter(v=>v!==OWNER&&!v.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(v))}
(async()=>{const r={status:'FAIL',matches:[],error:null};let b;try{b=await chromium.launch({headless:true});const s=sa(),x=await loginTry(b,s.username,s.password);await x.p.goto(U('superadmin/companies/27/users'),{waitUntil:'domcontentloaded'});const f=x.p.locator('form[action$="/superadmin/companies/27/owner/reset-password"]');const nav=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await nav;const vals=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.textContent||'').filter(Boolean)),list=cand(await x.p.locator('body').innerText(),vals);await x.c.close();let owner=null;for(const v of list){const t=await loginTry(b,OWNER,v);if(t.ok){owner=t;break}await t.c.close()}if(!owner)throw Error('owner login unavailable');await owner.p.goto(U('company/clients'),{waitUntil:'domcontentloaded'});r.matches=await owner.p.evaluate(()=>{const q='P14 Клиент Аудит',all=[...document.querySelectorAll('*')].filter(e=>(e.textContent||'').includes(q));return all.slice(-20).map(e=>({tag:e.tagName,id:e.id||null,cls:e.className||null,data:Object.fromEntries([...e.attributes].filter(a=>a.name.startsWith('data-')).map(a=>[a.name,a.value])),text:(e.innerText||'').trim().replace(/\s+/g,' ').slice(0,500),html:e.outerHTML.slice(0,4000)}))});await owner.p.screenshot({path:path.join(OUT,'P14_CLIENT_ROW_DISCOVERY_1920x1080.png'),fullPage:false});r.status='PASS';await owner.c.close()}catch(e){r.error={name:e?.name||'Error',message:String(e?.message||e).slice(0,400)}}finally{if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(r,null,2));console.log(`P14_CLIENT_ROW_DISCOVERY=${r.status}`);process.exitCode=r.status==='PASS'?0:1}})();
